# -*- coding: utf-8 -*-
"""CUT Improvement Auto — Night Drive refinement for the approved React layout.
Only source CSS, vehicle debt fallback text and a derived banner image.
Does NOT edit built releases, frontend/dist, backend, DB, MAX, photos or backups.
Run from PROJECT/scripts, after install_cut_approved_design.py.
"""
from __future__ import annotations
import os, sys, shutil, hashlib, base64, zlib, tempfile
from pathlib import Path
from datetime import datetime

PAYLOAD = {'frontend/src/styles/cut-dashboard-layout.css': {'old': 'b80124331f220747fa01ce2a0db7dcd15d61d1f261d4ef04a1459497e1a3ae9a', 'new': '436f456169fb33fab96ba07273f4e43710cc466d10cc80f3698d1812cd6c441f', 'data': ''}, 'frontend/src/components/DashboardVehicleStateCard.tsx': {'old': '68077af0b550e96b656704fc8ca8321140ab750f08e5a7a42808245ceca23c75', 'new': '2f5cf92520bbd4990e33b97677c6feddabcbf5ffe228764b701f0ff9c57f8dfe', 'data': ''}, 'frontend/public/cut-night-assets/approved-night-hero.jpg': {'old': None, 'new': '9f12286a8431540cdd03b806e41b3ca918c5d4dbeaa467ce4f980d335d3339ec', 'data': ''}}
# Confirm the approved layout is still present; avoid injecting styles into an older App.
APP_SHA256 = 'b0d4602e1ae89d518cb5605a57a43f49dfee978ebbbdd71e4c09d29192fffd9a'

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temp = tempfile.mkstemp(prefix='.cut-night-refine-',suffix='.tmp',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(temp,path)
    finally:
        if os.path.exists(temp): os.unlink(temp)

def main() -> int:
    print('=== CUT Improvement Auto / Night Drive Refinement ===')
    script=Path(__file__).resolve()
    root=script.parent.parent
    if script.parent.name.lower() != 'scripts' or not (root/'backend/app/main.py').is_file():
        raise RuntimeError('Place this installer inside the existing PROJECT/scripts folder.')
    app=root/'frontend/src/App.tsx'
    if not app.is_file() or sha(app.read_bytes()) != APP_SHA256:
        raise RuntimeError('App.tsx differs from approved design. Nothing changed; do not overwrite custom work.')
    pending={}
    for rel,record in PAYLOAD.items():
        target=root/rel
        decoded=zlib.decompress(base64.b64decode(record['data']))
        if sha(decoded) != record['new']:
            raise RuntimeError('Embedded package corrupt: '+rel)
        existing=target.read_bytes() if target.is_file() else None
        if existing is not None and sha(existing)==record['new']:
            continue
        if record['old'] is None:
            if existing is not None: raise RuntimeError('Asset exists with different content; refusing: '+rel)
        elif existing is None or sha(existing) != record['old']:
            raise RuntimeError('Source changed since approved install; refusing: '+rel)
        pending[target]=decoded
    if not pending:
        print('OK: refinement already installed. Nothing to do.')
        return 0
    stamp=datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    backup=root.parent/'CUT_Improvement_Auto_DevArchive'/'night_refinement_backups'/stamp
    backup.mkdir(parents=True,exist_ok=False)
    previous={}
    for target in pending:
        original=target.read_bytes() if target.is_file() else None
        previous[target]=original
        if original is not None:
            copy=backup/target.relative_to(root)
            copy.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(target,copy)
            if sha(copy.read_bytes())!=sha(original):
                raise RuntimeError('Backup validation failed; no source files changed.')
    # Place the image before CSS (CSS becomes active last).
    order=sorted(pending,key=lambda p:(p.suffix=='.css',str(p)))
    changed=[]
    try:
        for target in order:
            atomic_write(target,pending[target])
            if sha(target.read_bytes()) != sha(pending[target]):
                raise RuntimeError('SHA mismatch after write: '+str(target))
            changed.append(target)
    except BaseException:
        for target in reversed(changed):
            old=previous[target]
            if old is None: target.unlink(missing_ok=True)
            else: atomic_write(target,old)
        raise
    print('OK: approved orange-headlight artwork installed for the DARK welcome banner.')
    print('OK: Night Drive topbar, cards, shadows and spacing refined.')
    print('OK: missing/invalid debt amount now shows a clear placeholder, not undefined.')
    print('OK: Light Drive CSS unchanged; existing theme selector retained.')
    print('BACKUP:',backup)
    print('CHANGED:',', '.join(str(p.relative_to(root)) for p in order))
    print('UNTOUCHED: active 0.1.0, frontend/dist, backend, database, MAX, .env, photos, backups, Git.')
    print('PREVIEW: http://127.0.0.1:5173/ — use Vite; do not build/activate yet.')
    return 0

if __name__=='__main__':
    try: raise SystemExit(main())
    except Exception as exc:
        print('INSTALL FAILED:',str(exc),file=sys.stderr)
        raise SystemExit(1)
